unsigned par(unsigned x){return __builtin_popcount(x)&1;}
unsigned slot(unsigned j,unsigned dc,unsigned bias){unsigned u=j<<1;return u|(par(u&51)^bias^dc);}
unsigned phys(unsigned r,unsigned k){return (((k>>10)*64+r)<<10)+(k&1023);}
unsigned value(unsigned r,unsigned k){unsigned x=k+0x9e3779b9u*(r+1);x^=x>>16;x*=0x85ebca6bu;x^=x>>13;return x;}
